result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "sched.py", "content": """"Learning-rate schedules.

All functions return a callable ``lr(step: int) -> float`` so they can be
composed (e.g. warmup wrapping a cosine schedule).
"""
import math


def step_decay(base_lr, gamma, step_size):
    """Drop the learning rate by ``gamma`` every ``step_size`` steps.

    lr(s) = base_lr * gamma ** (s // step_size)
    """
    def lr(step):
        if step < 0:
            raise ValueError("step must be non-negative")
        return base_lr * gamma ** (step // step_size)
    return lr


def cosine_annealing(base_lr, T_max, eta_min):
    """Cosine annealing from ``base_lr`` down to ``eta_min`` over T_max steps.

    lr(t) = eta_min + (base_lr - eta_min) * (1 + cos(pi * t / T_max)) / 2
    """
    def lr(step):
        if step < 0 or step > T_max:
            raise ValueError(f"step must be in [0, {T_max}]")
        cos_term = math.cos(math.pi * step / T_max)
        return eta_min + (base_lr - eta_min) * (1.0 + cos_term) / 2.0
    return lr


def linear_warmup(warmup_steps, schedule):
    """Wrap ``schedule`` with a linear warmup over ``warmup_steps`` steps.

    For step < warmup_steps:
        lr(s) = base_lr * (s + 1) / warmup_steps   (ramps base_lr/warmup_steps -> base_lr)
    Afterwards, the wrapped schedule takes over, evaluated at
    ``step - warmup_steps`` so it starts at its own base value.
    """
    def lr(step):
        if step < 0:
            raise ValueError("step must be non-negative")
        if step < warmup_steps:
            return schedule(warmup_steps - warmup_steps) * (step + 1) / warmup_steps
        return schedule(step - warmup_steps)
    return lr
